    "col.regle.titre": ["La règle à respecter", "The rule to follow"],
    "col.regle.texte": ["Votre page d'avis et votre carte s'adressent <strong>à tous vos clients, sans exception</strong>. Règles de Google : aucune contrepartie (remise, cadeau), aucun tri entre clients contents et mécontents, aucune pression sur place, aucune demande de contenu précis, aucun nombre d'avis à obtenir fixé à vos salariés.",
      "Your review page and your card are for <strong>all your customers, without exception</strong>. Google's rules: no incentive (discount, gift), no filtering between happy and unhappy customers, no pressure on the spot, no request for specific content, no review target set for your staff."],
    "col.chapo": ["Une même page pour tous vos clients : ils publient leur avis sur Google ou vous écrivent en privé.", "One page for all your customers: they post their review on Google or write to you privately."],
    "col.manque.titre": ["Il manque votre lien Google", "Your Google link is missing"],
    "col.manque.texte": ["Ajoutez dans <a href=\"#/fiche\">votre fiche</a> le lien pour laisser un avis Google (business.google.com, Lire les avis, Obtenir plus d'avis). Il doit commencer par https://.",
      "Add the link for leaving a Google review to <a href=\"#/fiche\">your details</a> (business.google.com, Read reviews, Get more reviews). It must start with https://."],
    "col.manque.note": ["Tant que ce lien manque, votre page d'avis reste fermée : le message privé n'est jamais proposé sans le bouton Google.",
      "Until this link is added, your review page stays closed: the private message is never offered without the Google button."],
    "col.page.titre": ["Votre page d'avis", "Your review page"],
    "col.page.texte": ["Quelle que soit la note choisie, la page propose les deux mêmes boutons : publier son avis sur Google, ou vous écrire en privé.",
      "Whatever rating is chosen, the page offers the same two buttons: post a review on Google, or write to you privately."],
    "col.imprimer": ["Imprimer la carte A6", "Print the A6 card"], "col.ouvrir": ["Ouvrir la page", "Open the page"], "col.copier": ["Copier le lien", "Copy the link"],
    "col.bouton.google": ["Le bouton Google de cette page ouvre : ", "The Google button on this page opens: "],
    "col.adresse.demo": ["Cette adresse est celle de la démonstration. N'imprimez la carte qu'une fois l'espace installé à son adresse définitive : le code de la carte contient cette adresse.",
      "This is the demo address. Only print the card once your account is set up at its final address: the card's code contains this address."],
    "col.copie": ["Lien copié.", "Link copied."], "col.copie.echec": ["La copie n'a pas abouti : sélectionnez le lien ci-dessus pour le copier.", "Copying didn't work: select the link above to copy it."],
    "wa.titre": ["Demander par WhatsApp", "Ask via WhatsApp"],
